import { Howl, Howler } from 'howler'
import { useSyncExternalStore } from 'react'

/**
 * The car's engine, horn and knocks.
 *
 * No music, no ambience — the same restraint as everywhere else in this world.
 * What they are for is feedback: the engine says how fast you are going and
 * whether you are on the throttle, and the knock says you hit something rather
 * than glided past it. Neither is decoration, and neither plays when nothing is
 * happening.
 *
 * The samples are generated by `scripts/make-sounds.mjs`. The engine is a
 * single 50Hz loop played back at a rate driven by speed, which is how a real
 * engine sound is done and why one 21KB file covers idle through boost.
 *
 * The knocks and the horn are pools. A single knock sample was audibly a single
 * knock sample the moment anything was hit twice, and now that the world is
 * full of loose props that is most of the time — the pitch jitter below was
 * always a patch over the fact that there was only one waveform to jitter.
 */

const ENGINE_SOURCE = '/sounds/engine.wav'

/** Graded light to heavy by the generator; `playImpact` relies on that order. */
const IMPACT_SOURCES = [
  '/sounds/impact-1.wav',
  '/sounds/impact-2.wav',
  '/sounds/impact-3.wav',
  '/sounds/impact-4.wav',
  '/sounds/impact-5.wav',
] as const

const HORN_SOURCES = ['/sounds/horn-1.wav', '/sounds/horn-2.wav'] as const

/** Top speed with boost, from `CAR.controlsAcceleratingMaxSpeedBoost`. */
const MAX_SPEED = (0.11 * 3) / 17

const ENGINE = {
  /** Playback rate at a standstill and at full tilt. */
  rate: { min: 0.62, max: 2.1 },
  volume: { min: 0.1, max: 0.42 },
  /** Per-frame easing on the rate, so a bump does not blip the pitch. */
  easing: 0.12,
}

/** Below this the knock is the suspension settling, not a collision. */
const IMPACT_FLOOR = 1.5
const IMPACT_CEILING = 12
/** Two bodies in one contact report twice; this collapses the pair. */
const IMPACT_COOLDOWN_MS = 90

const STORAGE_KEY = 'kevinotuteye:sound'

/* ------------------------------------------------------------------ */
/* Mute                                                                */
/* ------------------------------------------------------------------ */

/**
 * Muting is a stored preference, and it is the reason this module has a store
 * at all: the toggle is a DOM button rendered outside the canvas, so its state
 * has to survive a render, while everything else here is called from inside the
 * frame loop and must not cause one.
 */
let muted = false
const listeners = new Set<() => void>()

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

export function isMuted(): boolean {
  return muted
}

export function useMuted(): boolean {
  // The server has no preference to read, so it renders the unmuted icon and
  // the client corrects it on hydration if it has to.
  return useSyncExternalStore(subscribe, isMuted, () => false)
}

export function setMuted(next: boolean) {
  if (muted === next) return
  muted = next
  Howler.mute(next)
  try {
    window.localStorage.setItem(STORAGE_KEY, next ? 'off' : 'on')
  } catch {
    // Private browsing. The preference simply does not persist.
  }
  listeners.forEach((listener) => listener())
}

export function toggleMuted() {
  setMuted(!muted)
}

/* ------------------------------------------------------------------ */
/* Loading                                                             */
/* ------------------------------------------------------------------ */

type Sounds = { engine: Howl; horns: Howl[]; impacts: Howl[] }

let sounds: Sounds | null = null
let engineProgress = 0
let lastImpact = 0

/**
 * Builds the sounds on first use.
 *
 * Deferred rather than done at module scope because this module is imported by
 * the DOM chrome, which renders on the server. Nothing is fetched until the
 * world is actually running.
 */
function ensure(): Sounds | null {
  if (typeof window === 'undefined') return null
  if (sounds) return sounds

  // The stored preference is read here rather than at import time, so it has
  // to be published: the toggle has already rendered by now, off the SSR
  // default, and a visitor who muted last time would otherwise see a button
  // claiming the sound is on until something else happened to re-render it.
  let stored = false
  try {
    stored = window.localStorage.getItem(STORAGE_KEY) === 'off'
  } catch {
    stored = false
  }
  if (stored !== muted) {
    muted = stored
    listeners.forEach((listener) => listener())
  }
  Howler.mute(muted)

  sounds = {
    engine: new Howl({ src: [ENGINE_SOURCE], loop: true, volume: 0 }),
    horns: HORN_SOURCES.map((src) => new Howl({ src: [src], volume: 0.35 })),
    impacts: IMPACT_SOURCES.map((src) => new Howl({ src: [src], volume: 0.5 })),
  }

  // Started immediately and left running for the life of the page. Browsers
  // will not let it through until the visitor has interacted; howler holds it
  // and releases it on the first gesture, which on this site is the first time
  // they touch the controls — so the engine arrives exactly when the car does.
  sounds.engine.play()

  // A tab in the background should not be heard from. Muting rather than
  // pausing keeps the engine loop's phase, so returning does not restart it.
  document.addEventListener('visibilitychange', () => {
    Howler.mute(muted || document.hidden)
  })

  return sounds
}

/* ------------------------------------------------------------------ */
/* Playback                                                            */
/* ------------------------------------------------------------------ */

/**
 * Follows the car. Called every frame.
 *
 * `speed` is metres per millisecond, as everything about the car is.
 * `accelerating` lifts the pitch when the throttle is down but the car has not
 * answered yet — pulling away and pushing against something both sound like
 * effort rather than silence.
 */
export function updateEngine(speed: number, accelerating: boolean) {
  const loaded = ensure()
  if (!loaded) return

  const target = Math.min(1, Math.abs(speed) / MAX_SPEED) + (accelerating ? 0.2 : 0)
  engineProgress += (Math.min(1.15, target) - engineProgress) * ENGINE.easing

  loaded.engine.rate(
    ENGINE.rate.min + (ENGINE.rate.max - ENGINE.rate.min) * engineProgress
  )
  loaded.engine.volume(
    ENGINE.volume.min + (ENGINE.volume.max - ENGINE.volume.min) * engineProgress
  )
}

let lastHorn = -1

export function playHorn() {
  const loaded = ensure()
  if (!loaded) return

  // Never the same horn twice running. With a pool of two, picking at random
  // repeats half the time, which is worse than not having a pool.
  const next = (lastHorn + 1) % loaded.horns.length
  lastHorn = next

  // Every horn stopped rather than just the one being played: two horns at once
  // is a chord, not a horn, and with a pool they are no longer the same Howl.
  loaded.horns.forEach((sound) => sound.stop())
  loaded.horns[next].play()
}

/**
 * `strength` is the impact speed along the contact normal, in m/s.
 *
 * The sample is chosen by force rather than at random. The pool is graded light
 * to heavy, so a nudge picks from the short bright end and a real collision
 * from the long dark end — which is the difference between a knock that tells
 * you how hard you hit something and one that only tells you that you did.
 */
export function playImpact(strength: number) {
  const loaded = ensure()
  if (!loaded || strength < IMPACT_FLOOR) return

  const now = performance.now()
  if (now - lastImpact < IMPACT_COOLDOWN_MS) return
  lastImpact = now

  const force = Math.min(
    1,
    (strength - IMPACT_FLOOR) / (IMPACT_CEILING - IMPACT_FLOOR)
  )

  // Force sets the centre of the window; the jitter is what stops a row of
  // near-identical hits — driving along a line of boards — from selecting the
  // same sample every time.
  const spread = (Math.random() - 0.5) * 1.6
  const index = Math.round(
    Math.min(
      loaded.impacts.length - 1,
      Math.max(0, force * (loaded.impacts.length - 1) + spread)
    )
  )

  const sound = loaded.impacts[index]
  const id = sound.play()
  sound.volume(0.25 + force * 0.75, id)
  // Kept, but much narrower than it was. With five envelopes to draw on the
  // pitch no longer has to carry the variation on its own, and a wide spread
  // now just makes the pool sound out of tune with itself.
  sound.rate(1.06 - force * 0.14 + (Math.random() - 0.5) * 0.07, id)
}
